    fields("c", 1250, 1, 0);
    TEST_ASSERT_EQUAL(900, el("c")->h);
    tops(225, 450, 675);
    lay("<body style='margin:0'><div id=a style='font-size:10px;line-height:0.5px;line-height:399.99px'><div id=b style=''><div id=c style='line-height:-2px'>a<br>b<br>c<br>d</div></div></div></body>");
    fields("a", 399, 0, 99);
    fields("b", 399, 0, 99);
    fields("c", 399, 0, 99);
    TEST_ASSERT_EQUAL(1599, el("c")->h);
    tops(399, 799, 1199);
    lay("<body style='margin:0'><div id=a style='font-size:5px'><div id=b style='font-size:5px;line-height:0.75em;line-height:15.5px'><div id=c style='font-size:40px'>a<br>b<br>c<br>d</div></div></div></body>");
    fields("a", 0, 0, 0);
    fields("b", 15, 0, 50);
    fields("c", 15, 0, 50);
    TEST_ASSERT_EQUAL(62, el("c")->h);
    tops(15, 31, 46);
