    fields("a", 0, 0, 0);
    fields("b", 333, 1, 0);
    fields("c", 333, 1, 0);
    TEST_ASSERT_EQUAL(852, el("c")->h);
    tops(213, 426, 639);
    lay("<body style='margin:0'><div id=a style=''><div id=b style='font-size:5px'><div id=c style=''>a<br>b<br>c<br>d</div></div></div></body>");
    fields("a", 0, 0, 0);
    fields("b", 0, 0, 0);
    fields("c", 0, 0, 0);
    TEST_ASSERT_EQUAL(40, el("c")->h);
    tops(10, 20, 30);
    lay("<body style='margin:0'><div id=a style='line-height:0'><div id=b style='font-size:18px;line-height:120px'><div id=c style='font-size:64px'>a<br>b<br>c<br>d</div></div></div></body>");
    fields("a", 1, 1, 0);
    fields("b", 120, 0, 0);
    fields("c", 120, 0, 0);
    TEST_ASSERT_EQUAL(480, el("c")->h);
    tops(120, 240, 360);
    lay("<body style='margin:0'><div id=a style='font-size:10px'><div id=b style=''><div id=c style='line-height:4000%'>a<br>b<br>c<br>d</div></div></div></body>");
    fields("a", 0, 0, 0);
